import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";

export default function Register() {

  const navigate = useNavigate();

  const [user, setUser] = useState({

    name: "",

    email: "",

    password: ""

  });

  const [generatedOtp, setGeneratedOtp] = useState("");

  const [enteredOtp, setEnteredOtp] = useState("");

  const [otpVerified, setOtpVerified] = useState(false);


  const handleChange = (e) => {

    setUser({

      ...user,

      [e.target.name]: e.target.value

    });

  };


  const sendOtp = () => {

    if (!user.email) {

      alert("Please Enter Email First");

      return;

    }

    const otp = Math.floor(

      100000 + Math.random() * 900000

    ).toString();

    setGeneratedOtp(otp);

    alert("OTP : " + otp);

  };


  const verifyOtp = () => {

    if (enteredOtp === generatedOtp) {

      setOtpVerified(true);

      alert("OTP Verified Successfully ✅");

    }

    else {

      alert("Invalid OTP ❌");

    }

  };


  const handleRegister = (e) => {

    e.preventDefault();

    if (!otpVerified) {

      alert("Please Verify OTP First");

      return;

    }


    // IMPORTANT LINE

    localStorage.setItem(

      "user",

      JSON.stringify(user)

    );


    alert("Registration Successful ✅");


    navigate("/login");

  };


  return (

    <div

      style={{

        height: "100vh",

        display: "flex",

        justifyContent: "center",

        alignItems: "center",

        background: "#0f172a"

      }}

    >

      <form

        onSubmit={handleRegister}

        style={{

          background: "white",

          padding: "30px",

          width: "400px",

          borderRadius: "15px"

        }}

      >

        <h1>Register</h1>


        <input

          type="text"

          name="name"

          placeholder="Full Name"

          onChange={handleChange}

          style={inputStyle}

        />


        <input

          type="email"

          name="email"

          placeholder="Email"

          onChange={handleChange}

          style={inputStyle}

        />


        <button

          type="button"

          onClick={sendOtp}

          style={btnStyle}

        >

          Send OTP

        </button>


        <input

          type="text"

          placeholder="Enter OTP"

          value={enteredOtp}

          onChange={(e)=>

          setEnteredOtp(e.target.value)

          }

          style={inputStyle}

        />


        <button

          type="button"

          onClick={verifyOtp}

          style={btnStyle}

        >

          Verify OTP

        </button>


        <input

          type="password"

          name="password"

          placeholder="Password"

          onChange={handleChange}

          style={inputStyle}

        />


        <button

          type="submit"

          style={{

            ...btnStyle,

            background:"#16a34a"

          }}

        >

          Register

        </button>


        <p>

          Already have account ?

          <Link to="/login">

            Login

          </Link>

        </p>

      </form>

    </div>

  );

}


const inputStyle = {

  width:"100%",

  padding:"12px",

  marginBottom:"12px"

};


const btnStyle = {

  width:"100%",

  padding:"12px",

  marginBottom:"12px",

  background:"#2563eb",

  color:"white",

  border:"none",

  borderRadius:"8px",

  cursor:"pointer"

};
